export function jlrGdpSvg(lang,kind){
 if(typeof lang!=='string'||!['fr','en'].includes(lang)||typeof kind!=='string'||!JLR_GDP_KINDS.includes(kind))throw new TypeError('Invalid JLR GDP figure variant');
 return FIGURES[`${kind}-${lang}`];
}
export function jlrGdpReferences(kind,sources){
 if(typeof kind!=='string'||!JLR_GDP_KINDS.includes(kind)||typeof sources!=='string')throw new TypeError('Invalid JLR GDP figure references');
 const references=sources.trim()?sources.trim().split(/\s+/u):[],required=JLR_GDP_REQUIRED_SOURCES[kind];
 if(references.length!==required.length||new Set(references).size!==references.length||references.some(id=>!required.includes(id)))throw new TypeError('Incomplete or invalid JLR GDP source references');
 return Object.freeze(references);
}
export function jlrGdpInlineSvg(lang,kind){
 // Controlled static originals only; no user-controlled markup reaches set:html.
 return jlrGdpSvg(lang,kind).replace(/^<svg /u,'<svg style="width:100%;height:auto" ');
}
